import { writeOutput } from "./codegen";

const DOCS_URL = "https://integrations.expensify.com/Integration-Server/doc/";

export async function generate(): Promise<void> {
  writeOutput(
    "expensify",
    [
      "// Auto-generated from Expensify Integration Server docs.",
      `// Source: ${DOCS_URL}`,
      "// Regenerate: cd turbo && pnpm -F @vm0/firewalls-generator generate:expensify",
      "//",
      "// DO NOT EDIT THIS FILE MANUALLY.",
      "",
      'import type { FirewallConfig } from "../firewall-types";',
      "",
      "export const expensifyFirewall = {",
      '  name: "expensify",',
      '  description: "Expensify Integration Server",',
      "  apis: [",
      "    {",
      '      base: "https://integrations.expensify.com/Integration-Server/ExpensifyIntegrations",',
      "      auth: {},",
      "      permissions: [],",
      "    },",
      "  ],",
      "} as const satisfies FirewallConfig;",
      "",
    ].join("\n"),
  );
}
